// payment-method.js
// Reusable "Payment Method" dropdown component (name + icon), meant to be hosted
// on GitHub Pages and imported by any page with a single <script type="module"> import.
//
// Usage in a page:
//
//   import { initPaymentDropdown } from "https://YOUR_GH_USERNAME.github.io/YOUR_REPO/payment-method.js";
//
//   const pm = initPaymentDropdown({
//     container: document.getElementById("pmSlot"), // an empty <div id="pmSlot"></div>
//     selected: "Cash",
//     onChange: (method) => {
//       // method = { id, label, color }
//       console.log("Selected:", method.id);
//     }
//   });
//
//   // Later, read/set the value from your own code:
//   pm.getValue();        // "Cash"
//   pm.setValue("Bikash"); // change selection programmatically
//
// NOTE ON ICONS: Cash and Bank use simple generic inline icons. bKash and Nagad
// use their official logos (provided by the site owner), embedded directly as
// inline SVG so the whole component stays in this ONE file and works from a
// single hosted link (e.g. GitHub Pages) on any site that imports it — no
// separate image files or extra network requests needed. If you ever want to
// swap a logo, use the "customLogos" option below without touching this file.

